{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2188-06-24 20:30:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee. I’ll be your doctor during this stay. You’re here because of nausea and vomiting again?"
    },
    {
      "turn_number": 2,
      "time": "2188-06-24 20:31:00",
      "speaker": "Patient",
      "text": "Yes, just like last time. I felt okay the day after I got home, but then it came back—nausea, then vomiting. I can’t keep anything down."
    },
    {
      "turn_number": 3,
      "time": "2188-06-24 20:32:00",
      "speaker": "Doctor",
      "text": "I see. No fever, pain, or diarrhea?"
    },
    {
      "turn_number": 4,
      "time": "2188-06-24 20:33:00",
      "speaker": "Patient",
      "text": "No, just nausea and vomiting. The pain only comes with the vomiting."
    },
    {
      "turn_number": 5,
      "time": "2188-06-24 20:34:00",
      "speaker": "Doctor",
      "text": "Okay. Given your history of gastroparesis and recent discharge, we’ll start with IV fluids and anti-nausea meds. We also need to check if your C. diff treatment is complete."
    },
    {
      "turn_number": 6,
      "time": "2188-06-24 20:35:00",
      "speaker": "Patient",
      "text": "I took the last vancomycin dose yesterday. Is that okay?"
    },
    {
      "turn_number": 7,
      "time": "2188-06-24 20:36:00",
      "speaker": "Doctor",
      "text": "Yes, that matches your record. We’ll keep monitoring for symptoms. Your labs show low albumin and mild anemia, so malnutrition is a concern."
    },
    {
      "turn_number": 8,
      "time": "2188-06-24 20:37:00",
      "speaker": "Patient",
      "text": "I’ve been losing weight. I just can’t eat."
    },
    {
      "turn_number": 9,
      "time": "2188-06-24 20:38:00",
      "speaker": "Doctor",
      "text": "That’s why we’re considering a GJ tube again. It helped before, right?"
    },
    {
      "turn_number": 10,
      "time": "2188-06-24 20:39:00",
      "speaker": "Patient",
      "text": "Yes, it did. I was able to get nutrition and felt better. But I was hoping to avoid another procedure."
    },
    {
      "turn_number": 11,
      "time": "2188-06-24 20:40:00",
      "speaker": "Doctor",
      "text": "I understand. But given how quickly you relapsed, it might be the best option now to prevent future admissions."
    },
    {
      "turn_number": 12,
      "time": "2188-06-24 20:41:00",
      "speaker": "Patient",
      "text": "Okay, if it’s the right thing. When would it happen?"
    },
    {
      "turn_number": 13,
      "time": "2188-06-24 20:42:00",
      "speaker": "Doctor",
      "text": "We’ll schedule it for tomorrow. The interventional radiology team will place it using imaging guidance."
    },
    {
      "turn_number": 14,
      "time": "2188-06-25 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. We’re set to do the GJ tube placement this morning. Any questions before we proceed?"
    },
    {
      "turn_number": 15,
      "time": "2188-06-25 08:16:00",
      "speaker": "Patient",
      "text": "Will I be asleep? Is it painful?"
    },
    {
      "turn_number": 16,
      "time": "2188-06-25 08:17:00",
      "speaker": "Doctor",
      "text": "You’ll get sedation—fentanyl and midazolam—so you’ll be drowsy and comfortable. Local numbing at the site too. Most patients tolerate it well."
    },
    {
      "turn_number": 17,
      "time": "2188-06-25 08:18:00",
      "speaker": "Patient",
      "text": "Okay, that sounds manageable."
    },
    {
      "turn_number": 18,
      "time": "2188-06-25 13:00:00",
      "speaker": "Doctor",
      "text": "The GJ tube was placed successfully. The tip is in the jejunum, and the balloon is inflated in the stomach. We’ll wait 24 hours before using the gastric port."
    },
    {
      "turn_number": 19,
      "time": "2188-06-25 13:01:00",
      "speaker": "Patient",
      "text": "That’s great. When can we start the feeds?"
    },
    {
      "turn_number": 20,
      "time": "2188-06-25 13:02:00",
      "speaker": "Doctor",
      "text": "We’ll start continuous tube feeds tonight through the jejunal port. Nutrition recommends Jevity 1.5 at 50 mL/hour to start."
    },
    {
      "turn_number": 21,
      "time": "2188-06-25 13:03:00",
      "speaker": "Patient",
      "text": "What’s Jevity?"
    },
    {
      "turn_number": 22,
      "time": "2188-06-25 13:04:00",
      "speaker": "Doctor",
      "text": "It’s a high-calorie, high-protein formula designed for tube feeding. It has vitamins and minerals too."
    },
    {
      "turn_number": 23,
      "time": "2188-06-26 07:00:00",
      "speaker": "Doctor",
      "text": "Your labs are stable. WBC is low but not concerning. Potassium and magnesium are normal. We’re watching for refeeding syndrome."
    },
    {
      "turn_number": 24,
      "time": "2188-06-26 07:01:00",
      "speaker": "Patient",
      "text": "What’s refeeding syndrome?"
    },
    {
      "turn_number": 25,
      "time": "2188-06-26 07:02:00",
      "speaker": "Doctor",
      "text": "When someone who’s malnourished starts eating again, the body shifts fluids and electrolytes. We monitor closely and give thiamine to prevent complications."
    },
    {
      "turn_number": 26,
      "time": "2188-06-26 07:03:00",
      "speaker": "Patient",
      "text": "Oh, okay. So that’s why I’m getting thiamine?"
    },
    {
      "turn_number": 27,
      "time": "2188-06-26 07:04:00",
      "speaker": "Doctor",
      "text": "Exactly. Just a precaution. You’re doing well so far."
    },
    {
      "turn_number": 28,
      "time": "2188-06-27 09:00:00",
      "speaker": "Doctor",
      "text": "You’ve been tolerating the tube feeds well. We’re increasing to 75 mL/hour for 16 hours, then a break."
    },
    {
      "turn_number": 29,
      "time": "2188-06-27 09:01:00",
      "speaker": "Patient",
      "text": "That means I can go home soon?"
    },
    {
      "turn_number": 30,
      "time": "2188-06-27 09:02:00",
      "speaker": "Doctor",
      "text": "Possibly. We want to make sure you’re stable on the feeds and your nausea is controlled."
    },
    {
      "turn_number": 31,
      "time": "2188-06-27 09:03:00",
      "speaker": "Patient",
      "text": "What about my cancer? I haven’t had treatment in a while."
    },
    {
      "turn_number": 32,
      "time": "2188-06-27 09:04:00",
      "speaker": "Doctor",
      "text": "You’re not on active chemo now. Your CEA tumor marker was normal, which is reassuring. But we’ll need to follow up with oncology."
    },
    {
      "turn_number": 33,
      "time": "2188-06-27 09:05:00",
      "speaker": "Patient",
      "text": "I was on anastrozole and paclitaxel before. Should I restart?"
    },
    {
      "turn_number": 34,
      "time": "2188-06-27 09:06:00",
      "speaker": "Doctor",
      "text": "That’s a conversation for your oncologist. Right now, the priority is stabilizing your nutrition and symptoms."
    },
    {
      "turn_number": 35,
      "time": "2188-06-28 10:00:00",
      "speaker": "Doctor",
      "text": "Your port was accessed today for labs. All levels are stable. No signs of infection or electrolyte issues."
    },
    {
      "turn_number": 36,
      "time": "2188-06-28 10:01:00",
      "speaker": "Patient",
      "text": "Good. I feel stronger already."
    },
    {
      "turn_number": 37,
      "time": "2188-06-29 14:00:00",
      "speaker": "Doctor",
      "text": "We reviewed your imaging. The GJ tube is in the right place. You’re doing well—no vomiting, and you’re tolerating feeds."
    },
    {
      "turn_number": 38,
      "time": "2188-06-29 14:01:00",
      "speaker": "Patient",
      "text": "Can I try a little food by mouth?"
    },
    {
      "turn_number": 39,
      "time": "2188-06-29 14:02:00",
      "speaker": "Doctor",
      "text": "Yes, we can try small amounts of low-fat foods. But the tube will remain your main source of nutrition."
    },
    {
      "turn_number": 40,
      "time": "2188-06-30 08:00:00",
      "speaker": "Doctor",
      "text": "You’re making great progress. We’re planning discharge tomorrow if all goes well."
    },
    {
      "turn_number": 41,
      "time": "2188-06-30 08:01:00",
      "speaker": "Patient",
      "text": "What do I need to do at home?"
    },
    {
      "turn_number": 42,
      "time": "2188-06-30 08:02:00",
      "speaker": "Doctor",
      "text": "Continue the tube feeds at 75 mL/hour for 16 hours. Use Ensure Original three times a day. Add extra water every 6 hours."
    },
    {
      "turn_number": 43,
      "time": "2188-06-30 08:03:00",
      "speaker": "Patient",
      "text": "And my medications?"
    },
    {
      "turn_number": 44,
      "time": "2188-06-30 08:04:00",
      "speaker": "Doctor",
      "text": "Same as before—metoclopramide, omeprazole, morphine for pain, and ondansetron if nauseous. But hold off on Denosumab until you see oncology."
    },
    {
      "turn_number": 45,
      "time": "2188-06-30 08:05:00",
      "speaker": "Patient",
      "text": "Why stop Denosumab?"
    },
    {
      "turn_number": 46,
      "time": "2188-06-30 08:06:00",
      "speaker": "Doctor",
      "text": "It’s used to protect bones in metastatic cancer, but your team wants to reassess your treatment plan first."
    },
    {
      "turn_number": 47,
      "time": "2188-07-01 09:00:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home. A nurse will visit to help with the tube, and you’ll follow up with gastroenterology and oncology."
    },
    {
      "turn_number": 48,
      "time": "2188-07-01 09:01:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better."
    },
    {
      "turn_number": 49,
      "time": "2188-07-01 09:02:00",
      "speaker": "Doctor",
      "text": "You did well. Call if you have fever, redness at the tube site, or can’t keep feeds down."
    },
    {
      "turn_number": 50,
      "time": "2188-07-01 09:03:00",
      "speaker": "Patient",
      "text": "I will. And I’ll keep my appointments."
    },
    {
      "turn_number": 51,
      "time": "2188-07-01 09:04:00",
      "speaker": "Doctor",
      "text": "Perfect. We’ll see you in clinic soon."
    },
    {
      "turn_number": 52,
      "time": "2188-07-01 09:05:00",
      "speaker": "Patient",
      "text": "One more thing—my mood has been low. Should I talk to someone?"
    },
    {
      "turn_number": 53,
      "time": "2188-07-01 09:06:00",
      "speaker": "Doctor",
      "text": "Yes, please mention that at your follow-up. Depression and anxiety are common, and we can help."
    },
    {
      "turn_number": 54,
      "time": "2188-07-01 09:07:00",
      "speaker": "Patient",
      "text": "I’d appreciate that."
    },
    {
      "turn_number": 55,
      "time": "2188-07-01 09:08:00",
      "speaker": "Doctor",
      "text": "We’ll make sure it’s on your follow-up list. Take care."
    },
    {
      "turn_number": 56,
      "time": "2188-07-01 09:09:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 57,
      "time": "2188-07-01 09:10:00",
      "speaker": "Doctor",
      "text": "You’re welcome. The transport team will take you home shortly."
    },
    {
      "turn_number": 58,
      "time": "2188-07-01 09:11:00",
      "speaker": "Patient",
      "text": "I’m ready."
    },
    {
      "turn_number": 59,
      "time": "2188-07-01 09:12:00",
      "speaker": "Doctor",
      "text": "We’ll check in with you next week by phone to make sure things are going smoothly."
    },
    {
      "turn_number": 60,
      "time": "2188-07-01 09:13:00",
      "speaker": "Patient",
      "text": "That’s reassuring. Thank you."
    },
    {
      "turn_number": 61,
      "time": "2188-07-01 09:14:00",
      "speaker": "Doctor",
      "text": "You’ve worked hard. Keep it up."
    },
    {
      "turn_number": 62,
      "time": "2188-07-01 09:15:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 63,
      "time": "2188-07-01 09:16:00",
      "speaker": "Doctor",
      "text": "Have a safe trip home."
    },
    {
      "turn_number": 64,
      "time": "2188-07-01 09:17:00",
      "speaker": "Patient",
      "text": "Thank you again."
    },
    {
      "turn_number": 65,
      "time": "2188-07-01 09:18:00",
      "speaker": "Doctor",
      "text": "Take care of yourself."
    },
    {
      "turn_number": 66,
      "time": "2188-07-01 09:19:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 67,
      "time": "2188-07-01 09:20:00",
      "speaker": "Doctor",
      "text": "We’re here if you need us."
    }
  ],
  "summary": {
    "admission_start": "2188-06-24 20:18:00",
    "admission_end": "2188-07-01 12:44:00",
    "summary_paragraph": "A woman with metastatic breast cancer and a history of gastroparesis was readmitted three days after discharge due to recurrent nausea and vomiting. She had completed a course of vancomycin for C. difficile colitis and was found to be malnourished. A GJ tube was placed on hospital day two, and jejunal feeding was initiated to address nutritional needs and prevent refeeding syndrome. She tolerated tube feeds well, with gradual improvement in symptoms. Her medications were continued, except for holding Denosumab pending oncology follow-up. She was discharged home with services, on a regimen of continuous tube feeds, oral supplements, and home medications, with plans for outpatient follow-up in gastroenterology and oncology.",
    "problems": [
      "Gastroparesis",
      "Unspecified severe protein-calorie malnutrition",
      "Secondary malignant neoplasm of liver and intrahepatic bile duct",
      "Secondary malignant neoplasm of bone",
      "Personal history of transient ischemic attack (TIA), and cerebral infarction without residual deficits",
      "Personal history of malignant neoplasm of breast",
      "Enterocolitis due to Clostridium difficile, not specified as recurrent",
      "Neoplasm related pain (acute) (chronic)",
      "Gastro-esophageal reflux disease without esophagitis",
      "Hypothyroidism, unspecified",
      "Major depressive disorder, single episode, unspecified",
      "Anxiety disorder, unspecified",
      "Body mass index [BMI] 22.0-22.9, adult"
    ]
  }
}
